type DSU struct {
    comps  int
    Parent []int
    Size   []int
}

func NewDSU(n int) *DSU {
    parent := make([]int, n+1)
    for i := range parent {
        parent[i] = i
    }
    return &DSU{
        comps:  n,
        Parent: parent,
        Size:   make([]int, n+1),
    }
}

func (d *DSU) find(node int) int {
    if d.Parent[node] != node {
        d.Parent[node] = d.find(d.Parent[node])
    }
    return d.Parent[node]
}

func (d *DSU) union(u, v int) bool {
    pu := d.find(u)
    pv := d.find(v)
    if pu == pv {
        return false
    }

    d.comps--
    if d.Size[pu] < d.Size[pv] {
        pu, pv = pv, pu
    }
    d.Size[pu] += d.Size[pv]
    d.Parent[pv] = pu
    return true
}

func (d *DSU) components() int {
    return d.comps
}

func validTree(n int, edges [][]int) bool {
    if len(edges) > n-1 {
        return false
    }

    dsu := NewDSU(n)
    for _, edge := range edges {
        u, v := edge[0], edge[1]
        if !dsu.union(u, v) {
            return false
        }
    }
    return dsu.components() == 1
}
